// ───────────────────────────── AGSL (same source as the web preview) ─────────────────────────────

private const val CUE_AGSL = """
// AI Visual Cue — AGSL (Android 13 / API 33+)
// fragCoord: px, origin top-left. Geometry uniforms are in dp (uScale = density).
uniform float2 uRes;
uniform float uScale;
uniform float2 uCenter;
uniform float2 uHalf;
uniform float uRadius;
uniform float uElev;
uniform float uBevel;
uniform float uShadow;
uniform float uShadowBlur;
uniform float uShadowOff;
uniform float uFill;
uniform float uGlowW;
uniform float uGlow;
uniform float uScrim;
uniform float uPhase;
uniform float uPhaseAmt;
uniform float2 uHl;
uniform float uTime;
uniform float4 uP;
uniform float3 uC0;
uniform float3 uC1;
uniform float3 uC2;
uniform float3 uPos;
uniform float uStopCount;
uniform float uGradType;
uniform float2 uDir;
uniform float3 uNeutral;
uniform float uEdgeSoft;
uniform float uOpacity;

float sdRound(float2 p, float2 b, float r) {
    float2 q = abs(p) - b + float2(r);
    return length(max(q, float2(0.0))) + min(max(q.x, q.y), 0.0) - r;
}
float hash12(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453); }
float3 oklabToSrgb(float3 c) {
    float l_ = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
    float m_ = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
    float s_ = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;
    float l = l_ * l_ * l_;
    float m = m_ * m_ * m_;
    float s = s_ * s_ * s_;
    float3 lin = float3( 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
                        -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
                        -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s);
    lin = clamp(lin, 0.0, 1.0);
    float3 hi = 1.055 * pow(lin, float3(1.0 / 2.4)) - 0.055;
    float3 lo = lin * 12.92;
    return mix(lo, hi, step(float3(0.0031308), lin));
}
float3 ramp(float g) {
    float3 c = uC0;
    if (uStopCount > 1.5) { c = mix(uC0, uC1, smoothstep(uPos.x, uPos.y, g)); }
    if (uStopCount > 2.5) { c = mix(c, uC2, smoothstep(uPos.y, uPos.z, g)); }
    return oklabToSrgb(c);
}

// Material: Soft Glow
float3 material(float3 n, float g, float2 fc, float2 p) {
    float3 c = ramp(g);
    float rim = pow(1.0 - n.z, 3.0) * uP.y;
    return mix(c, ramp(1.0) + 0.08, clamp(rim, 0.0, 1.0));
}

float4 over(float4 src, float4 dst) { return src + dst * (1.0 - src.a); }

float4 cue(float2 fc) {
    float2 p = fc / uScale;                       // dp, y down
    float2 lp = p - uCenter;
    float2 hb = max(uHalf, float2(0.5));
    float rr = min(uRadius, min(hb.x, hb.y));
    float d = sdRound(lp, hb, rr);

    // surface normal from the SDF (circular bevel profile)
    float e = 0.75;
    float2 gr = float2(sdRound(lp + float2(e, 0.0), hb, rr) - sdRound(lp - float2(e, 0.0), hb, rr),
                       sdRound(lp + float2(0.0, e), hb, rr) - sdRound(lp - float2(0.0, e), hb, rr));
    float gl = length(gr);
    float2 gOut = gl > 0.0001 ? gr / gl : float2(0.0);
    float s = max(-d, 0.0);
    float bv = clamp(uBevel, 0.5, min(hb.x, hb.y));
    float u = 1.0 - clamp(s / bv, 0.0, 1.0);
    float nz = sqrt(max(1.0 - u * u, 0.0));
    float3 n = normalize(float3(gOut * u * uElev, mix(1.0, nz, uElev) + 0.001));

    // gradient coordinate: highlight core -> rim / bottom
    float3 H = normalize(float3(uHl.x, uHl.y, 1.0));
    float2 q = lp / hb;
    float gPlanar = clamp(length(q - uHl) / 1.35, 0.0, 1.0);
    float gLinear = clamp(dot(q, uDir) * 0.5 + 0.5, 0.0, 1.0);
    float gNormal = clamp((1.0 - dot(n, H)) / 1.6 + max(n.y, 0.0) * 0.25, 0.0, 1.0);
    float g = uGradType > 0.5 ? mix(gLinear, gNormal, uElev * 0.4) : mix(gPlanar, gNormal, uElev);
    float gEdge = 0.1 + 0.75 * (0.5 + 0.5 * sin(atan(lp.y, lp.x) * 2.0 + uTime * 0.9));
    g = mix(gEdge, g, uFill);

    float3 col = material(n, g, fc, p);
    float3 axis = float3(sin(uPhase) * 0.7071, -sin(uPhase) * 0.7071, cos(uPhase));
    float lit = smoothstep(-0.06, 0.06, dot(n, axis));
    col = mix(col, mix(uNeutral, col, lit), uPhaseAmt);
    col = clamp(col, 0.0, 1.0);

    // coverage (+ edge-glow mode when uFill < 1)
    float w = 1.0 / uScale + uEdgeSoft;
    float cov = clamp(0.5 - d / w, 0.0, 1.0);
    float inner = mix(exp(-s / max(uGlowW, 1.0)), 1.0, uFill);
    float a = cov * inner * uOpacity;

    float glowR = 14.0 + 22.0 * uGlow;
    float ga = exp(-max(d, 0.0) / glowR) * uGlow * 0.55 * (1.0 - cov) * uOpacity;
    float3 gcol = ramp(0.55);

    float ds = sdRound(lp - float2(0.0, uShadowOff), hb * 0.9, rr * 0.9);
    float sb = max(uShadowBlur, 1.0);
    float sa = (1.0 - smoothstep(-sb, sb, ds)) * uShadow * 0.38;
    float3 scol = ramp(0.0) * 0.45;

    float4 o = float4(0.0, 0.0, 0.0, uScrim);
    o = over(float4(scol * sa, sa), o);
    o = over(float4(gcol * ga, ga), o);
    o = over(float4(col * a, a), o);
    return o;
}

half4 main(float2 fragCoord) {
    return half4(cue(fragCoord));
}
